#include "cf_karplus.h"
#include "cf_math.h"
#include <limits.h>
#include <stddef.h>
static uint16_t r16(const uint8_t*s,size_t o){return pk_cf_ld16(s,o);}
static uint32_t r32(const uint8_t*s,size_t o){return pk_cf_ld32(s,o);}
static void w16(uint8_t*s,size_t o,uint16_t v){pk_cf_st16(s,o,v);}
static void w32(uint8_t*s,size_t o,uint32_t v){pk_cf_st32(s,o,v);}
static int16_t s16(uint16_t u){return (u&0x8000u)?(int16_t)(-1-(int16_t)(uint16_t)~u):(int16_t)u;}
static int32_t s32(uint32_t u){return (u&0x80000000u)?-1-(int32_t)~u:(int32_t)u;}
static uint32_t u32(int32_t s){return s>=0?(uint32_t)s:~(uint32_t)(-1-s);}
static int32_t asr(int32_t v,unsigned n){uint32_t b;if(!n)return v;b=u32(v)>>n;if(v<0)b|=(~0u)<<(32u-n);return s32(b);}
static int32_t mullo(int32_t a,int32_t b){return s32(pk_cf_mul_lo_u32(u32(a),u32(b)));}
static uint16_t tab16(const uint8_t*t,size_t i){return pk_cf_ld16(t,2u*i);}
static uint16_t env(uint8_t*s,size_t b,const pk_cf_karplus_tables*t){uint8_t st=s[b];int32_t v=s32(r32(s,b+0xc));switch(st){case 0:if(s[b+7]||s[b+4])s[b]=1;break;case 1:v=s32(u32(v)+(uint32_t)r16(s,b+0x20));w32(s,b+0xc,u32(v));if(s[b+4]){if(v>0xffffe){s[b]=4;if(v>=0x100000){v=0xfffff;w32(s,b+0xc,u32(v));}}}else if(v>0xffffe){s[b]=s[b+6]?4:3;if(v>=0x100000){v=0xfffff;w32(s,b+0xc,u32(v));}}break;case 2:break;case 3:if(!s[b+7]&&(s[b+4]||!s[b+0x10]))s[b]=4;break;case 4:if(s[b+7])s[b]=1;else{v=s32(u32(v)-(uint32_t)r16(s,b+0x22));w32(s,b+0xc,u32(v));if(v<=0){v=0;w32(s,b+0xc,0);s[b]=s[b+4]?1:0;}}break;default:break;}if(s[b+1]!=1&&s[b+1]!=2)return(uint16_t)((u32(v)>>4)&0xffffu);{const uint8_t*c=s[b+1]==1?t->envelope1:t->envelope2;uint32_t raw,idx,nx;int32_t f,a,z;if(!c)return 0;raw=u32(v);idx=(raw>>10)&0x7ffu;nx=(idx+1)&0x7ffu;f=(int32_t)(raw&0x3ffu);a=(int32_t)tab16(c,idx);z=(int32_t)tab16(c,nx);return(uint16_t)(a+asr(mullo(z-a,f),10));}}
static uint32_t rnd(pk_cf_karplus_rng*r){const uint32_t a=0x5851f42d,b=0x4c957f2d;uint32_t ol=r->low,oh=r->high,acc=pk_cf_mul_lo_u32(ol,a),pl=pk_cf_mul_lo_u32(ol,b),ph=pk_cf_mul_hi_u32(ol,b),nl,carry,nh;acc+=pk_cf_mul_lo_u32(oh,b);nl=pl+1u;carry=nl<pl;nh=acc+ph+carry;r->low=nl;r->high=nh;return nh&0x7fffffffu;}
static int16_t noise(uint8_t*s,size_t b,pk_cf_karplus_rng*r){uint16_t c=r16(s,b);int16_t x;if(c){w16(s,b,(uint16_t)(c-1));return s16(r16(s,b+0x10));}w16(s,b,r16(s,b+2));x=s16((uint16_t)rnd(r));w16(s,b+0x10,(uint16_t)x);return x;}
/* THE FILTER'S TWO COEFFICIENTS ARE LOOP-INVARIANT (frame-cost work, 9 Oct
 * 2026). It read s[b+0xc] and s[b+0xe] every sample, but only karplus_update
 * writes them and that runs before the block -- filter itself writes only
 * b+0x10/0x14/0x18. Take them once per block instead; numerically identical. */
static void filter(uint8_t*s,size_t b,int32_t input,uint16_t coeff,uint16_t coeff2){int32_t velocity=s32(r32(s,b+0x18)),product=mullo(velocity,(int32_t)coeff),first,second,feedback;if(product<0)product=s32(u32(product)+0xffffu);first=s32(r32(s,b+0x10));first=s32(u32(first)+u32(asr(product,16)));if(first>32767)first=32767;else if(first<-32767)first=-32767;w32(s,b+0x10,u32(first));second=s32(u32(input)-u32(first));product=mullo(velocity,(int32_t)coeff2);second=s32(u32(second)-u32(asr(product,10)));if(second>32767)second=32767;else if(second<-32767)second=-32767;w32(s,b+0x14,u32(second));feedback=mullo(second,(int32_t)coeff);if(feedback<0)feedback=s32(u32(feedback)+0xffffu);velocity=s32(u32(velocity)+u32(asr(feedback,16)));if(velocity>32767)velocity=32767;else if(velocity<-32767)velocity=-32767;w32(s,b+0x18,u32(velocity));}
static int32_t bitfield(int32_t v,unsigned l,unsigned w){uint32_t mask=(1u<<w)-1u,bits=(u32(v)>>l)&mask,sign=1u<<(w-1u);if(bits&sign)bits|=~mask;return s32(bits);}
static int32_t sat16(int32_t v){if(v>32767)return 32767;if(v<-32768)return -32768;return v;}
int pk_cf_karplus_render(uint8_t*s,int16_t*d,uint32_t n,const pk_cf_karplus_tables*t,pk_cf_karplus_rng*r){uint32_t i;if(!s||!d||!t||!r)return 0;const uint16_t fco=r16(s,0xaa),fco2=r16(s,0xa8);for(i=0;i<n;i++){uint16_t amp=env(s,0x74,t),ec=r16(s,0xc4),et=r16(s,0xc2);int32_t ex=0,ring,fin,out,prod;uint32_t delay,ri,age;uint16_t wi;if(et>ec){ec=(uint16_t)(ec+1);w16(s,0xc4,ec);ex=(int32_t)noise(s,0x60,r);}else w16(s,0xc4,0xffffu);delay=r32(s,0x10c8);wi=r16(s,0x10d4);ri=((uint32_t)wi-delay)&0x7ffu;ring=(int32_t)r16(s,0xc6+(size_t)ri*2u);fin=s32((uint32_t)(ring+ex));filter(s,0x9c,fin,fco,fco2);wi=r16(s,0x10d4);age=r32(s,0x10d8);ri=(uint32_t)wi&0x7ffu;out=s32(r32(s,0xac));w16(s,0xc6+(size_t)ri*2u,(uint16_t)out);w16(s,0x10d4,(uint16_t)(wi+1u));if(age<=0x210u){uint8_t mode=s[5];if(mode==0){int32_t nz=(int32_t)noise(s,0x60,r);if(age<=0x110u){if(age<=0x8fu){int32_t tr=s32(u32(nz)+u32(mullo(nz,4)));tr=s32(u32(nz)+u32(mullo(tr,2)));tr=bitfield(tr,4,26);out=s32(u32(out)+u32(tr));}else{int32_t tapered=mullo((int32_t)(0x110u-age),nz);uint32_t logical=u32(tapered)>>8;int32_t scaled=mullo(44,s32(logical));out=s32(u32(out)+u32(asr(scaled,6)));}age+=1u;out=sat16(out);}else{age+=1u;out=sat16(out);}}else if(mode==2){int32_t nz=(int32_t)noise(s,0x60,r);if(age<=0x2f0u){if(age<=0xefu){int32_t tr=s32(u32(nz)+u32(mullo(nz,4)));tr=s32(u32(nz)+u32(mullo(tr,2)));tr=bitfield(tr,4,26);out=s32(u32(out)+u32(tr));}else{int32_t tapered=mullo((int32_t)(0x2f0u-age),nz);uint32_t logical=u32(tapered)>>10;int32_t scaled=mullo(44,s32(logical));out=s32(u32(out)+u32(asr(scaled,6)));}if(out>32767)out=32767;else if(out<-32767)out=-32767;}age+=1u;}else age+=1u;}w32(s,0x10d8,age);if(s[0xb8]){d[i]=0;continue;}prod=asr(mullo(out,(int32_t)amp),16);prod=asr(mullo(prod,(int32_t)s[6]),8);if(prod>INT16_MAX)prod=INT16_MAX;else if(prod<INT16_MIN)prod=INT16_MIN;d[i]=(int16_t)prod;}return 1;}
